code.css:
.grid {
  display: grid;
  grid-template-columns: repeat(9, 1fr);
  gap: 10px;
  width: min(70vmin, 360px);
}

.grid i {
  aspect-ratio: 1;
  animation: breathe 2.4s ease-in-out infinite;
  /* a negative delay starts each cell part-way through the loop */
  animation-delay: calc(var(--d) * -1s);
}

@keyframes breathe {
  0%,
  100% {
    transform: scale(0.2);
    background: #27343b;
  }
  50% {
    transform: scale(1);
    background: #2ad2ee;
  }
}

@media (prefers-reduced-motion: reduce) {
  .grid i {
    animation: none;
    transform: scale(0.6);
    background: #2ad2ee;
  }
}

code.js:
const grid = document.querySelector('.grid');
const size = 9;
const centre = (size - 1) / 2;

for (let i = 0; i < size * size; i++) {
  const cell = document.createElement('i');
  // the further a cell is from the centre, the later it breathes
  const distance = Math.hypot((i % size) - centre, Math.floor(i / size) - centre);
  cell.style.setProperty('--d', (distance * 0.22).toFixed(2));
  grid.append(cell);
}
